package com.edufun.portal.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="certificates") public class Certificate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long studentId; private Long examSessionId; private String certificateNumber; private String level; private String title; private Integer score; private LocalDateTime issuedAt=LocalDateTime.now(); public Long getId(){return id;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public Long getExamSessionId(){return examSessionId;} public void setExamSessionId(Long v){examSessionId=v;} public String getCertificateNumber(){return certificateNumber;} public void setCertificateNumber(String v){certificateNumber=v;} public String getLevel(){return level;} public void setLevel(String v){level=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public Integer getScore(){return score;} public void setScore(Integer v){score=v;} public LocalDateTime getIssuedAt(){return issuedAt;} public void setIssuedAt(LocalDateTime v){issuedAt=v;} }
